.l24-boris-ip-tz-kompensaciya__lead {
  margin: 0 0 24px;
  font-size: 0.95rem;
  line-height: 1.55;
  color: var(--tz-muted);
  max-width: 62ch;
}
.l24-boris-ip-tz-kompensaciya__lead strong { color: #fff; }
.l24-boris-ip-tz-kompensaciya__split {
  display: grid;
  grid-template-columns: minmax(0, 1.15fr) minmax(0, 0.95fr);
  gap: 24px;
  align-items: stretch;
}
.l24-boris-ip-tz-kompensaciya__panel {
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 10px;
  padding: 20px 18px;
}
.l24-boris-ip-tz-kompensaciya__panel-title {
  margin: 0 0 14px;
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--tz-gold);
}
.l24-boris-ip-tz-kompensaciya__timeline-svg {
  display: block;
  width: 100%;
  height: auto;
  max-height: 220px;
}
.l24-boris-ip-tz-kompensaciya__steps {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  margin: 16px 0 0;
  padding: 0;
  list-style: none;
}
.l24-boris-ip-tz-kompensaciya__step {
  margin: 0;
  padding: 12px 10px;
  background: rgba(0, 0, 0, 0.2);
  border-radius: 8px;
  border-left: 3px solid var(--tz-accent);
  font-size: 0.78rem;
  line-height: 1.4;
}
.l24-boris-ip-tz-kompensaciya__step:nth-child(2) { border-left-color: var(--tz-gold); }
.l24-boris-ip-tz-kompensaciya__step:nth-child(3) { border-left-color: var(--tz-mint); }
.l24-boris-ip-tz-kompensaciya__step strong {
  display: block;
  color: #fff;
  font-size: 0.82rem;
  margin-bottom: 4px;
}
.l24-boris-ip-tz-kompensaciya__comp-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  margin: 0 0 14px;
}
.l24-boris-ip-tz-kompensaciya__comp-card {
  padding: 12px 11px;
  border-radius: 8px;
  background: rgba(0, 0, 0, 0.22);
  border: 1px solid rgba(255, 255, 255, 0.08);
}
.l24-boris-ip-tz-kompensaciya__comp-card--wide {
  grid-column: 1 / -1;
  border-color: rgba(236, 201, 75, 0.35);
  background: rgba(197, 48, 48, 0.15);
}
.l24-boris-ip-tz-kompensaciya__comp-label {
  display: block;
  font-size: 0.68rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--tz-muted);
  margin-bottom: 4px;
}
.l24-boris-ip-tz-kompensaciya__comp-value {
  font-size: 1.05rem;
  font-weight: 800;
  color: #fff;
  line-height: 1.2;
}
.l24-boris-ip-tz-kompensaciya__comp-note {
  margin: 0;
  font-size: 0.76rem;
  line-height: 1.45;
  color: var(--tz-muted);
}
.l24-boris-ip-tz-kompensaciya__comp-note em {
  font-style: normal;
  color: var(--tz-mint);
  font-weight: 600;
}
.l24-boris-ip-tz-kompensaciya__roles {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 18px;
  padding-top: 16px;
  border-top: 1px solid rgba(255, 255, 255, 0.12);
}
.l24-boris-ip-tz-kompensaciya__role {
  font-size: 0.72rem;
  font-weight: 600;
  padding: 6px 10px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.08);
  color: var(--tz-ink);
}
